parameters.jsCode:
const output = [];

for (const item of $input.all()) {
  for (const [key, file] of Object.entries(item.binary ?? {})) {

    output.push({
      json: {
        ...item.json,
        fileName: file.fileName,
        mimeType: file.mimeType,
        fileExtension:
          file.fileExtension ??
          file.fileName?.split('.').pop()?.toLowerCase()
      },

      binary: {
        data: file
      }
    });
  }
}

return output;

