parameters.jsCode:
const vergleich = $input.first().json.output;

// Die ursprünglich extrahierten Angebote aus dem Aggregate holen
const angebote = $('Aggregate').first().json.angebote.map(a => a.output);

return angebote.map(angebot => {

  // Passende KI-Bewertung anhand des Anbieternamens suchen
  const bewertung = (vergleich.bewertungen ?? []).find(
    b =>
      b.anbieter?.trim().toLowerCase() ===
      angebot.anbieter?.trim().toLowerCase()
  ) ?? {};

  return {
    json: {
      anbieter: angebot.anbieter ?? null,
      angebotsdatum: angebot.angebotsdatum ?? null,
      projekt: angebot.projekt ?? null,

      leistungen: (angebot.leistungen ?? [])
        .map(l =>
          `${l.beschreibung}: ${l.preis ?? 'k.A.'} ${angebot.waehrung ?? ''}`
        )
        .join('\n'),

      gesamtpreis: angebot.gesamtpreis ?? null,
      waehrung: angebot.waehrung ?? null,
      ausfuehrungszeitraum: angebot.ausfuehrungszeitraum ?? null,

      hinweise: (angebot.hinweise ?? []).join('\n'),

      rang: bewertung.rang ?? null,
      bewertung: bewertung.status ?? null,

      staerken: (bewertung.staerken ?? []).join('\n'),
      schwaechen: (bewertung.schwaechen ?? []).join('\n'),
      auffaelligkeiten: (bewertung.auffaelligkeiten ?? []).join('\n'),

      begruendung: bewertung.begruendung ?? null
    }
  };
});

/*
  Baut je Angebot einen zusammenhängenden Text für den Vector Store.
  Der Node davor liefert ein flaches Objekt mit Einzelfeldern. Ein Embedding
  braucht aber Fließtext, denn gesucht wird nach Bedeutung und nicht nach Feldern.
*/
return $input.all().map((item) => {
  const a = item.json;
  const t = [];

  t.push('Anbieter: ' + (a.anbieter || 'unbekannt'));
  if (a.projekt) t.push('Projekt: ' + a.projekt);
  if (a.angebotsdatum) t.push('Angebotsdatum: ' + a.angebotsdatum);
  if (a.gesamtpreis !== null && a.gesamtpreis !== undefined) {
    t.push('Gesamtpreis: ' + a.gesamtpreis + ' ' + (a.waehrung || ''));
  }
  if (a.ausfuehrungszeitraum) t.push('Ausführungszeitraum: ' + a.ausfuehrungszeitraum);
  if (a.leistungen) t.push('\nLeistungen:\n' + a.leistungen);
  if (a.hinweise) t.push('\nHinweise:\n' + a.hinweise);

  // Die Bewertung gehört mit hinein, sonst kann man später nicht danach fragen.
  if (a.bewertung) t.push('\nBewertung: ' + a.bewertung + (a.rang ? ', Rang ' + a.rang : ''));
  if (a.staerken) t.push('Stärken:\n' + a.staerken);
  if (a.schwaechen) t.push('Schwächen:\n' + a.schwaechen);
  if (a.auffaelligkeiten) t.push('Auffälligkeiten:\n' + a.auffaelligkeiten);
  if (a.begruendung) t.push('Begründung: ' + a.begruendung);

  return { json: { ...a, suchtext: t.join('\n') } };
});

/*
  Baut aus dem Vergleich eine lesbare Vorlage für die Freigabemail.

  Eine Freigabe, bei der nur "bitte prüfen" steht, ist eine Formalie. Wer
  zustimmen soll, muss sehen, was bewertet wurde und warum.
*/
const eingang = $input.first().json;
const v = eingang.output || {};
const bewertungen = v.bewertungen || [];

const z = [];
z.push('VERGLEICH VON ' + bewertungen.length + ' ANGEBOTEN');
z.push('');
z.push('Vergleichbarkeit: ' + (v.vergleichbarkeit || 'keine Angabe'));
z.push('Empfehlung: ' + (v.empfohlenes_angebot || 'keine eindeutige Empfehlung'));
z.push('');

// Nach Rang sortieren, damit die Empfehlung oben steht. Angebote ohne Rang
// ans Ende, statt sie wegzulassen.
const sortiert = bewertungen.slice().sort(
  (a, b) => (a.rang ?? 99) - (b.rang ?? 99)
);

for (const b of sortiert) {
  z.push('----------------------------------------');
  z.push((b.rang ? 'Rang ' + b.rang + ': ' : '') + (b.anbieter || 'unbekannt') +
         '   [' + (b.status || 'ohne Status') + ']');
  if ((b.staerken || []).length) z.push('Stärken: ' + b.staerken.join('; '));
  if ((b.schwaechen || []).length) z.push('Schwächen: ' + b.schwaechen.join('; '));
  if ((b.auffaelligkeiten || []).length) {
    z.push('Auffälligkeiten: ' + b.auffaelligkeiten.join('; '));
  }
  if (b.begruendung) z.push('Begründung: ' + b.begruendung);
}

z.push('');
z.push('Gesamtfazit: ' + (v.gesamtfazit || 'keine Angabe'));

return [{ json: { ...eingang, vorlage: z.join('\n'), anzahl: bewertungen.length } }];

