parameters.jsCode:
/*
  Wertet die Antwort aus der Freigabemail aus.

  Der Vorgabewert steht hier, bevor die Antwort überhaupt gelesen wird:
  Ohne ausdrückliche Zustimmung gilt der Vergleich als abgelehnt. Bleibt die
  Antwort aus oder kommt etwas Unverständliches zurück, wird nichts abgelegt.
  Schweigen darf keine Zustimmung sein.
*/
const vorgang = $('Basic LLM Chain').first().json;
const a = $input.first().json.data || {};

let entscheidung = 'ablehnen';
const gemeldet = String(a.Entscheidung || '').trim().toLowerCase();
if (['freigeben', 'mit anmerkung freigeben', 'ablehnen'].includes(gemeldet)) {
  entscheidung = gemeldet;
}

return [{
  json: {
    ...vorgang,
    freigabe: entscheidung,
    freigegeben: entscheidung !== 'ablehnen',
    freigabe_anmerkung: String(a.Anmerkung || '').trim(),
    freigabe_zeit: a.respondedAt || new Date().toISOString(),
  },
}];
